/// <summary>
/// Extension of RetailOrderCalculator
/// </summary>
[ExtensionOf(classStr(RetailOrderCalculator))]
internal final class METRetailOrderCalculatorCls_Extension
{
}

Method.Source:
    /// <summary>
    /// GetRetroDiscount
    /// </summary>
    /// <param name = "_targetOfferId">targetOfferId</param>
    /// <returns>Map</returns>
    public Map metGetRetroDiscount(RetailOfferIdEx3 _targetOfferId)
    {
        Map salesLineDiscountMap = new Map(Types::String, Types::Class);

        Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine crtSalesLine;
        CLRObject clrSalesLines, enumeratorSalesLine, clrDiscountLines, enumeratorDiscountLine;

        this.priceCalculated = false;

        this.calculateDiscountsForOrderV2(true);

        clrSalesLines = crtSalesTransaction.get_SalesLines();
        enumeratorSalesLine = clrSalesLines.GetEnumerator();

        while (enumeratorSalesLine.MoveNext())
        {
            crtSalesLine = enumeratorSalesLine.get_Current();
            InventTransId inventTransId = crtSalesLine.get_LineId();

            if (this.metIsDiscountAlreadyApplied(inventTransId, _targetOfferId))
            {
                continue;
            }

            clrDiscountLines = crtSalesLine.get_DiscountLines();
            enumeratorDiscountLine = clrDiscountLines.GetEnumerator();

            while (enumeratorDiscountLine.MoveNext())
            {
                Microsoft.Dynamics.Commerce.Runtime.DataModel.DiscountLine crtDiscountLine = enumeratorDiscountLine.get_Current();

                if (crtDiscountLine.get_OfferId() == _targetOfferId)
                {
                    salesLineDiscountMap.insert(inventTransId, crtDiscountLine);
                }
            }
        }

        return salesLineDiscountMap;
    }

    /// <summary>
    /// IsDiscountAlreadyApplied
    /// </summary>
    /// <param name = "_inventTransId">inventTransId</param>
    /// <param name = "_offerId">offerId</param>
    /// <returns>boolean value</returns>
    private boolean metIsDiscountAlreadyApplied(InventTransId _inventTransId, RetailOfferIdEx3 _offerId)
    {
        RetailSalesDiscountLine salesDiscountLine;
        METRetroDiscountSalesInvoiceTransaction retroDiscountTrans;

        select firstonly RecId from salesDiscountLine
            where salesDiscountLine.InventTransId == _inventTransId
                && salesDiscountLine.PeriodicDiscountOfferId == _offerId;

        if (salesDiscountLine.RecId == 0)
        {
            select firstonly RecId from retroDiscountTrans
                where retroDiscountTrans.Posted == NoYes::Yes
                    && retroDiscountTrans.OfferId == _offerId
                    && retroDiscountTrans.InventTransId == _inventTransId;

            return retroDiscountTrans.RecId != 0;
        }

        return true;
    }
